svg.script:
(() => {
  const RAW_URL =
    "https://raw.githubusercontent.com/Mikasa237/sanpi-poker-online/main/tunnel.json";
  const CDN_URL =
    "https://cdn.jsdelivr.net/gh/Mikasa237/sanpi-poker-online@main/tunnel.json";
  const status = document.getElementById("status");
  const enter = document.getElementById("enter");

  async function fetchJson(url, timeoutMs = 6000) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const response = await fetch(`${url}?t=${Date.now()}`, {
        cache: "no-store",
        signal: controller.signal
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      return await response.json();
    } finally {
      clearTimeout(timer);
    }
  }

  function targetFor(baseUrl) {
    const base = String(baseUrl || "").replace(/\/+$/, "");
    const hash = location.hash.startsWith("#owner=") ? location.hash : "";
    return hash ? `${base}/host${hash}` : `${base}/online.html`;
  }

  async function healthCheck(baseUrl) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 7000);
    try {
      const response = await fetch(`${baseUrl}/api/health?t=${Date.now()}`, {
        cache: "no-store",
        signal: controller.signal
      });
      if (!response.ok) return false;
      const health = await response.json();
      return health.ok === true;
    } catch {
      return false;
    } finally {
      clearTimeout(timer);
    }
  }

  async function connect() {
    try {
      let runtime;
      try {
        runtime = await fetchJson(RAW_URL);
      } catch {
        runtime = await fetchJson(CDN_URL);
      }
      const baseUrl = String(runtime.url || "").replace(/\/+$/, "");
      if (!/^https:\/\/[a-z0-9-]+\.trycloudflare\.com$/i.test(baseUrl)) {
        throw new Error("当前牌桌地址尚未发布");
      }
      const target = targetFor(baseUrl);
      enter.setAttribute("href", target);
      if (!(await healthCheck(baseUrl))) {
        throw new Error("电脑端牌桌尚未就绪");
      }
      status.textContent = "已连接，正在进入…";
      location.replace(target);
    } catch {
      status.textContent = "牌桌暂时离线，请确认电脑已开机联网";
      enter.setAttribute(
        "href",
        "https://github.com/Mikasa237/sanpi-poker-online"
      );
    }
  }

  connect();
})();
